using namespace std;
const int MAXN = 1005;
struct Point {
    int x, y;
};
int n, m;
char grid[MAXN][MAXN];
int dist[MAXN][MAXN];
Point prev[MAXN][MAXN];
queue<Point> q;
vector<Point> shortestPath(Point source, Point dest) {
    // Initialize distance array
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            dist[i][j] = -1;
        }
    }
    dist[source.x][source.y] = 0;
    // BFS traversal
    q.push(source);
    while (!q.empty()) {
        Point curr = q.front();
        q.pop();
        if (curr.x == dest.x && curr.y == dest.y) {
            break;
        }
        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};
        for (int i = 0; i < 4; i++) {
            int nx = curr.x + dx[i];
            int ny = curr.y + dy[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                grid[nx][ny] != '#' && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[curr.x][curr.y] + 1;
                prev[nx][ny] = curr;
                q.push((Point){nx, ny});
            }
        }
    }
    // Construct path
    vector<Point> path;
    Point curr = dest;
    while (curr.x != source.x || curr.y != source.y) {
        path.push_back(curr);
        curr = prev[curr.x][curr.y];
    }
    path.push_back(source);
    reverse(path.begin(), path.end());
