```go
package main

import (
	"fmt"
	"math"
)

func uniqueSumMultiPowers(arr []int) int {
	// If array is empty, return 0
	if len(arr) == 0 {
		return 0
	}

	// Get unique values
	uniqueMap := make(map[int]bool)
	var uniqueArr []int
	var pos, neg int
	for _, num := range arr {
		if !uniqueMap[num] {
			uniqueArr = append(uniqueArr, num)
			uniqueMap[num] = true

			// Count negative and positive values
			if num > 0 {
				pos++
			} else if num < 0 {
				neg++
			}
		}
	}

	// Calculate the sum of unique values raised to their respective absolute values
	var powerSum float64
	for _, num := range uniqueArr {
		powerSum += math.Pow(math.Abs(float64(num)), math.Abs(float64(num)))
	}

	// Multiply the sum by the unique count of positive and negative elements
	finalResult := powerSum * float64(neg - pos)

	return int(finalResult)
}

func main() {
	arr := []int{1, 2, -1, -2, 3, -3, 2, 3}
	fmt.Println(uniqueSumMultiPowers(arr))  // Prints sum
}
```
Keep in mind that Go does not have built-in absolute function for integers like Python has. Therefore, `math.Abs` function is used which requires conversion of integers to and from float64. Finally, the resultant `finalResult` is also converted from float64 to integer using `int()` before being returned. 

